export async function getCloseLockInstructionAsync<
  TAccountLock extends string,
  TAccountLedger extends string,
  TAccountEscrow extends string,
  TAccountRentReceiver extends string,
  TAccountSystemProgram extends string,
  TProgramAddress extends Address = typeof BUCKSPAY_PROGRAM_ADDRESS,
>(
  input: CloseLockAsyncInput<TAccountLock, TAccountLedger, TAccountEscrow, TAccountRentReceiver, TAccountSystemProgram>,
  config?: { programAddress?: TProgramAddress },
): Promise<
  CloseLockInstruction<
    TProgramAddress,
    TAccountLock,
    TAccountLedger,
    TAccountEscrow,
    TAccountRentReceiver,
    TAccountSystemProgram
  >
> {
  // Program address.
  const programAddress = config?.programAddress ?? BUCKSPAY_PROGRAM_ADDRESS

  // Original accounts.
  const originalAccounts = {
    lock: { value: input.lock ?? null, isWritable: true },
    ledger: { value: input.ledger ?? null, isWritable: true },
    escrow: { value: input.escrow ?? null, isWritable: true },
    rentReceiver: { value: input.rentReceiver ?? null, isWritable: true },
    systemProgram: { value: input.systemProgram ?? null, isWritable: false },
  }
  const accounts = originalAccounts as Record<keyof typeof originalAccounts, ResolvedInstructionAccount>

  // Original args.
  const args = { ...input }

  // Resolve default values.
  if (!accounts.ledger.value) {
    accounts.ledger.value = await findLedgerPda(
      { lock: getAddressFromResolvedInstructionAccount('lock', accounts.lock.value) },
      { programAddress },
    )
  }
  if (!accounts.escrow.value) {
    accounts.escrow.value = await findEscrowPda(
      { lock: getAddressFromResolvedInstructionAccount('lock', accounts.lock.value) },
      { programAddress },
    )
  }
  if (!accounts.systemProgram.value) {
    accounts.systemProgram.value = '11111111111111111111111111111111' as Address<'11111111111111111111111111111111'>
  }

  const getAccountMeta = getAccountMetaFactory(programAddress, 'programId')
  return Object.freeze({
    accounts: [
      getAccountMeta('lock', accounts.lock),
      getAccountMeta('ledger', accounts.ledger),
      getAccountMeta('escrow', accounts.escrow),
      getAccountMeta('rentReceiver', accounts.rentReceiver),
      getAccountMeta('systemProgram', accounts.systemProgram),
    ],
    data: getCloseLockInstructionDataEncoder().encode(args as CloseLockInstructionDataArgs),
    programAddress,
  } as CloseLockInstruction<
    TProgramAddress,
    TAccountLock,
    TAccountLedger,
    TAccountEscrow,
    TAccountRentReceiver,
    TAccountSystemProgram
  >)
}

